/// Find `#[cfg(test)] mod ...` spans so their declarations are tagged
/// `in_test_module` and excluded from collision detection.
fn cfg_test_module_spans(text: &str) -> Vec<(usize, usize)> {
    let mut spans = Vec::new();
    let marker = regex::Regex::new(r"#\[cfg\(test\)\]\s*\n\s*mod\s+\w+[^{]*\{")
        .expect("static regex parses");
    for m in marker.find_iter(text) {
        let start = m.end() - 1; // at '{'
        let mut depth = 0usize;
        for (i, ch) in text[start..].char_indices() {
            match ch {
                '{' => depth += 1,
                '}' => {
                    depth -= 1;
                    if depth == 0 {
                        spans.push((start, start + i));
                        break;
                    }
                }
                _ => {}
            }
        }
    }
    spans
}

fn in_spans(spans: &[(usize, usize)], pos: usize) -> bool {
    spans.iter().any(|(a, b)| *a <= pos && pos <= *b)
}

/// Parse one source file into declarations + type re-exports.
fn parse_source(
    crate_name: &str,
    rel_path: &str,
    text: &str,
    decls: &mut Vec<TypeDecl>,
    reexports: &mut Vec<TypeReexport>,
) {
    let spans = cfg_test_module_spans(text);
    let decl_re = regex::Regex::new(r"(?m)^[ \t]*pub\s+(struct|enum)\s+([A-Z][A-Za-z0-9_]*)")
        .expect("static regex parses");
    for m in decl_re.captures_iter(text) {
        let whole = m.get(0).expect("group 0");
        let kind = match &m[1] {
            "struct" => TypeKind::Struct,
            _ => TypeKind::Enum,
        };
        decls.push(TypeDecl {
            crate_name: crate_name.to_owned(),
            name: m[2].to_owned(),
            kind,
            rel_path: rel_path.to_owned(),
            line: text[..whole.start()].lines().count() + 1,
            in_test_module: in_spans(&spans, whole.start()),
        });
    }
    // `pub use path::{A, B, C};` and single `pub use path::Name;`
    let braced = regex::Regex::new(r"(?m)^[ \t]*pub\s+use\s+([A-Za-z0-9_:]+)::\{([^}]*)\}\s*;")
        .expect("static regex parses");
    for m in braced.captures_iter(text) {
        let from = m[1].to_owned();
        for name in m[2].split(',') {
            let name = name.trim();
            if name.is_empty() {
                continue;
            }
            reexports.push(TypeReexport {
                crate_name: crate_name.to_owned(),
                name: name.to_owned(),
                from: from.clone(),
            });
        }
    }
    let single =
        regex::Regex::new(r"(?m)^[ \t]*pub\s+use\s+([A-Za-z0-9_]+)::([A-Z][A-Za-z0-9_]*)\s*;")
            .expect("static regex parses");
    for m in single.captures_iter(text) {
        reexports.push(TypeReexport {
            crate_name: crate_name.to_owned(),
            name: m[2].to_owned(),
            from: m[1].to_owned(),
        });
    }
}

/// The git binary. A constant so a caller grepping for the spawn finds it.
const GIT: &str = "git";

/// How many divergent paths a [`CensusSource::Worktree`] reason names before
/// it summarises the rest. Enough to identify the crate, short enough to read.
const NAMED_DIVERGENCES: usize = 5;

/// Is `path` an input this census actually reads?
///
/// Scoped to exactly the two shapes [`scan_workspace_types`] opens — the
/// per-crate manifest (the roster) and `src/**/*.rs` (the content). A dirty
/// `tests/` file or a stray artifact cannot change any number this module
/// prints, so it must not cost the scan its authority either; the predicate
/// is what keeps "authoritative" from degenerating into "nobody is working".
fn is_census_input(path: &str) -> bool {
    let Some(rest) = path.strip_prefix("crates/") else {
        return false;
    };
    let Some((_crate_dir, tail)) = rest.split_once('/') else {
        return false;
    };
    tail == "Cargo.toml" || (tail.starts_with("src/") && tail.ends_with(".rs"))
}

fn run_git(repo_root: &Path, args: &[&str]) -> Result<Vec<u8>, String> {
    let output = std::process::Command::new(GIT)
        .args(args)
        .current_dir(repo_root)
        .output()
        .map_err(|e| format!("cannot run `{GIT} {}`: {e}", args.join(" ")))?;
    if !output.status.success() {
        let detail = String::from_utf8_lossy(&output.stderr).trim().to_owned();
        let detail = if detail.is_empty() {
            format!("exit {:?}, no stderr", output.status.code())
        } else {
            detail
        };
        return Err(format!("`{GIT} {}` failed: {detail}", args.join(" ")));
    }
    Ok(output.stdout)
}

/// What can the tree at `repo_root` testify about?
///
/// [`CensusSource::Committed`] ONLY when every census input on disk is
/// byte-identical to `HEAD`. Anything else — one modified source, one
/// untracked `.rs`, no git at all — is [`CensusSource::Worktree`] carrying
/// the reason, because a number read from a tree that is not a commit is not
/// evidence about that commit, and a leg told otherwise reports green on
/// bytes nobody can push. That is not hypothetical: see [`CensusSource`].
pub fn census_source(repo_root: &Path) -> CensusSource {
    let rev = match run_git(repo_root, &["rev-parse", "HEAD"]) {
        Ok(bytes) => String::from_utf8_lossy(&bytes).trim().to_owned(),
        Err(reason) => return CensusSource::Worktree { reason },
    };
    if rev.len() != 40 || !rev.chars().all(|c| c.is_ascii_hexdigit()) {
        return CensusSource::Worktree {
            reason: format!("`{GIT} rev-parse HEAD` returned {rev:?}, which is not a commit id"),
        };
    }
    // `-z` so paths arrive raw: `core.quotePath` escaping would make a
    // non-ASCII path unparseable, and an unparseable path must never be
    // silently read as "clean".
    let status = match run_git(repo_root, &["status", "--porcelain", "-z", "--", "crates"]) {
        Ok(bytes) => bytes,
        Err(reason) => return CensusSource::Worktree { reason },
    };
    let mut divergent: Vec<String> = Vec::new();
    for chunk in status.split(|b| *b == 0) {
        if chunk.is_empty() {
            continue;
        }
        let text = String::from_utf8_lossy(chunk).into_owned();
        // Each record is `XY <path>`; a rename emits the destination that
        // way and the source as a bare following record. Both forms are
        // checked, so neither half of a rename can slip through.
        let path = match text.get(3..) {
            Some(tail) if text.as_bytes().get(2) == Some(&b' ') => tail.to_owned(),
            _ => text,
        };
        if is_census_input(&path) {
            divergent.push(path);
        }
    }
    if divergent.is_empty() {
        return CensusSource::Committed { rev };
    }
    divergent.sort_unstable();
    divergent.dedup();
    let shown = divergent
        .iter()
        .take(NAMED_DIVERGENCES)
        .cloned()
        .collect::<Vec<_>>()
        .join(", ");
    let more = divergent.len().saturating_sub(NAMED_DIVERGENCES);
    let tail = if more > 0 {
        format!(" (+{more} more)")
    } else {
        String::new()
    };
    CensusSource::Worktree {
        reason: format!(
            "{} census input(s) under crates/ differ from HEAD {}: {shown}{tail}",
            divergent.len(),
            &rev[..12]
        ),
    }
}

/// Walk `crates/*/src/**/*.rs` under `repo_root` and build the inventory.
///
/// The content is the tree's, ALWAYS — this reads what is on disk, including
/// your uncommitted work, which is what a developer wants to see. What it no
/// longer does is leave the reader guessing WHICH tree that was: the result
/// carries [`TypeInventory::source`] from [`census_source`], and every leg
/// that convicts the repository consults it first.
///
/// Errors (typed, never silent): a missing `crates/` root; a workspace with
/// zero crates; a crate with zero sources.
pub fn scan_workspace_types(repo_root: &Path) -> Result<TypeInventory, crate::InventoryError> {
    let crates_root = repo_root.join("crates");
    if !crates_root.is_dir() {
        return Err(crate::InventoryError::InvalidInput(format!(
            "no crates/ directory under {}",
            repo_root.display()
        )));
    }
    let mut entries: Vec<_> = std::fs::read_dir(&crates_root)
        .map_err(|e| crate::InventoryError::InvalidInput(format!("crates/ unreadable: {e}")))?
        .filter_map(|e| e.ok())
        .map(|e| e.path())
        .filter(|p| p.join("Cargo.toml").is_file())
        .collect();
    entries.sort();
    if entries.is_empty() {
        return Err(crate::InventoryError::InvalidInput(
            "crates/ contains no member crates".to_owned(),
        ));
    }

    let mut inventory_crates = Vec::new();
    for crate_dir in entries {
        let crate_name = crate_dir
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or_default()
            .to_owned();
        let src = crate_dir.join("src");
        let mut decls = Vec::new();
        let mut reexports = Vec::new();
        if src.is_dir() {
            let mut files = walk(src.clone());
            files.sort();
            if files.is_empty() {
                return Err(crate::InventoryError::InvalidInput(format!(
                    "crate {crate_name} has a src/ directory with no .rs files"
                )));
            }
            for f in files {
                let rel = f
                    .strip_prefix(&crate_dir)
                    .unwrap_or(&f)
                    .to_string_lossy()
                    .to_string();
                let text = std::fs::read_to_string(&f).map_err(|e| {
                    crate::InventoryError::InvalidInput(format!("cannot read {rel}: {e}"))
                })?;
                parse_source(&crate_name, &rel, &text, &mut decls, &mut reexports);
            }
        }
        inventory_crates.push(CrateTypes {
            crate_name,
            decls,
            reexports,
            has_lib: src.join("lib.rs").is_file(),
        });
    }

    let mut inventory = assemble(inventory_crates);
    inventory.source = census_source(repo_root);
    Ok(inventory)
}

fn walk(dir: std::path::PathBuf) -> Vec<std::path::PathBuf> {
    let mut out = Vec::new();
    let mut stack = vec![dir];
    while let Some(d) = stack.pop() {
        let Ok(entries) = std::fs::read_dir(&d) else {
            continue;
        };
        for e in entries.filter_map(|e| e.ok()) {
            let p = e.path();
            if p.is_dir() {
                stack.push(p);
            } else if p.extension().is_some_and(|x| x == "rs") {
                out.push(p);
            }
        }
    }
    out
}

/// Pure assembly: collisions, allowance matching, named zeros, counts, state.
/// Separated from I/O so the gate is testable on synthetic crate sets.
pub fn assemble(crates: Vec<CrateTypes>) -> TypeInventory {
    // name -> crate -> sites (non-test declarations only)
    let mut by_name: BTreeMap<String, BTreeMap<String, Vec<String>>> = BTreeMap::new();
    let mut enums = 0usize;
    let mut structs = 0usize;
    let mut reexport_count = 0usize;
    for c in &crates {
        for d in &c.decls {
            if d.in_test_module {
                continue;
            }
            match d.kind {
                TypeKind::Enum => enums += 1,
                TypeKind::Struct => structs += 1,
            }
            by_name
                .entry(d.name.clone())
                .or_default()
                .entry(c.crate_name.clone())
                .or_default()
                .push(format!("{}/{}:{}", c.crate_name, d.rel_path, d.line));
        }
        reexport_count += c.reexports.len();
    }

    let mut collisions = Vec::new();
    for (name, crate_sites) in by_name {
        if crate_sites.len() < 2 {
            continue;
        }
        let mut keys: Vec<String> = crate_sites.keys().cloned().collect();
        keys.sort();
        let crate_key = keys.join("+");
        let crate_names: Vec<String> = crate_sites.keys().cloned().collect();
        let sites: Vec<String> = crate_sites.into_values().flatten().collect();
        let allowance = ALLOWED_COLLISIONS
            .iter()
            .find(|(n, pair, _)| *n == name && *pair == crate_key)
            .map(|(_, _, reason)| reason.to_string());
        collisions.push(TypeCollision {
            name,
            crates: crate_names,
            sites,
            allowance,
        });
    }

    // Named zeros apply only to crates that HAVE a library surface. A
    // binary-only crate cannot declare a public type, so it is not a zero
    // to be named — see [`CrateTypes::has_lib`].
    let mut named_zeros = Vec::new();
    for c in &crates {
        if !c.has_lib {
            continue;
        }
        let has_public_decls = c.decls.iter().any(|d| !d.in_test_module);
        if !has_public_decls && c.reexports.is_empty() {
            if let Some((_, reason)) = NAMED_ZEROS.iter().find(|(n, _)| *n == c.crate_name) {
                named_zeros.push(format!("{}: {}", c.crate_name, reason));
            }
        }
    }

    let state = if collisions.iter().any(|c| c.allowance.is_none()) {
        ProbeState::Unknown
    } else {
        ProbeState::Known
    };

    TypeInventory {
        schema_version: "1".to_owned(),
        generated_by: "omp-inventory-map::types_inventory".to_owned(),
        state,
        counts: TypeCounts {
            enums,
            structs,
            reexports: reexport_count,
            crates_scanned: crates.len(),
            crates_with_types: crates
                .iter()
                .filter(|c| c.decls.iter().any(|d| !d.in_test_module) || !c.reexports.is_empty())
                .count(),
        },
        crates,
        collisions,
        missing: missing_vocabulary(),
        seam_decisions: seam_decisions(),
        named_zeros,
        // Handed in, so the caller owns the population: a fixture is judged
        // as given. Only `scan_workspace_types` overwrites this, with what
        // the tree it just read can actually testify about.
        source: CensusSource::Declared,
    }
}

impl TypeInventory {
    /// Every collision that has NO allowance row — each is a gate failure.
    pub fn disallowed(&self) -> Vec<&TypeCollision> {
        self.collisions
            .iter()
            .filter(|c| c.allowance.is_none())
            .collect()
    }

    /// Collisions where one side IS [`VOCABULARY_CRATE`] — the sharp class.
    ///
    /// Derived, never listed: the predicate is "does this collision involve
    /// the shared vocabulary crate", so a leaf crate landing does not move
    /// it. Measured 2026-09-03 on HEAD `6238c0f`: 29 collisions in, **2**
    /// out, and those 2 are exactly the two that had just appeared.
    pub fn vocabulary_splits(&self) -> Vec<&TypeCollision> {
        self.collisions
            .iter()
            .filter(|c| c.crates.iter().any(|k| k == VOCABULARY_CRATE))
            .collect()
    }

    /// Vocabulary splits carrying NO [`VOCABULARY_SPLITS`] row for their
    /// exact crate set — an untriaged split, which is the finding that must
    /// never accrue silently. A split whose crate set differs from its row's
    /// counts as untriaged: the same name splitting against `omp-types` from
    /// a different leaf is a new event, not a covered one.
    pub fn untriaged_vocabulary_splits(&self) -> Vec<&TypeCollision> {
        self.vocabulary_splits()
            .into_iter()
            .filter(|c| {
                let mut keys: Vec<&str> = c.crates.iter().map(String::as_str).collect();
                keys.sort_unstable();
                let key = keys.join("+");
                !VOCABULARY_SPLITS
                    .iter()
                    .any(|(name, set, _, _)| *name == c.name && *set == key)
            })
            .collect()
    }

    /// The gate. Errors name both crates per disallowed collision, plus any
    /// structural violation (anti-vacuity, unnamed zero, stale allowance,
    /// stale vocabulary-split row).
    ///
    /// Strictness is UNCHANGED by the vocabulary-split classification: every
    /// collision without an allowance is still refused, exactly as before. A
    /// [`VOCABULARY_SPLITS`] row is a REFUSAL that has been triaged and
    /// assigned an owner, not an amnesty — it changes what the error SAYS,
    /// never whether it fires. The classification exists because an
    /// undifferentiated wall of 29 refusals is an unread red, and an unread
    /// red is indistinguishable from an unwired gate at the only moment that
    /// matters.
    pub fn check(&self) -> Result<(), Vec<String>> {
        let mut errors = Vec::new();

        // Anti-vacuity: an empty scan set is an ERROR, never a pass.
        if self.counts.enums + self.counts.structs == 0 {
            errors.push(
                "anti-vacuity: zero public types discovered across the whole \
                 workspace — the scan set is empty, which is an error, never a \
                 clean inventory"
                    .to_owned(),
            );
        }

        // Disallowed collisions: name both crates. A vocabulary split — one
        // side IS the shared vocabulary crate — is called out as such and
        // carries its owner, because it is the class a human can act on.
        for c in self.disallowed() {
            let mut keys: Vec<&str> = c.crates.iter().map(String::as_str).collect();
            keys.sort_unstable();
            let key = keys.join("+");
            let triaged = VOCABULARY_SPLITS
                .iter()
                .find(|(name, set, _, _)| *name == c.name && *set == key);
            let detail = match (c.crates.iter().any(|k| k == VOCABULARY_CRATE), triaged) {
                (true, Some((_, _, owner, resolution))) => format!(
                    "VOCABULARY SPLIT against {VOCABULARY_CRATE}, TRIAGED — \
                     owner={owner}: {resolution}"
                ),
                (true, None) => format!(
                    "VOCABULARY SPLIT against {VOCABULARY_CRATE}, UNTRIAGED — a \
                     leaf crate declares a name the shared vocabulary crate \
                     already owns. Name it in VOCABULARY_SPLITS with an owner \
                     and a resolution, or delete the duplicate"
                ),
                (false, _) => "no allowance row carries a reason (see \
                               ALLOWED_COLLISIONS)"
                    .to_owned(),
            };
            errors.push(format!(
                "COLLISION {} declared by {}: {} — {detail}",
                c.name,
                c.crates.join(" + "),
                c.sites.join(", ")
            ));
        }

        // Unnamed zeros: a crate with no output at all that is not a named
        // zero is a finding, not silence.
        let named: Vec<&str> = NAMED_ZEROS.iter().map(|(n, _)| *n).collect();
        for c in &self.crates {
            // A binary-only crate has no library surface to be empty.
            if !c.has_lib {
                continue;
            }
            let has_decls = c.decls.iter().any(|d| !d.in_test_module);
            if !has_decls && c.reexports.is_empty() && !named.contains(&c.crate_name.as_str()) {
                errors.push(format!(
                    "NAMED-ZERO REQUIRED: crate {} declares no public type and \
                     re-exports none — name the zero with a reason in \
                     NAMED_ZEROS or give it a type",
                    c.crate_name
                ));
            }
        }

        // Stale allowance: a row that no longer corresponds to a real
        // collision is drift and must be pruned. (Validated against the REAL
        // workspace scan; synthetic fixtures skip this via `check_fixture`.)
        // AUTHORITY, added 2026-09-11: "no longer collides" is a claim about
        // the REPOSITORY, and a scratch tree cannot make it. Deleting one
        // uncommitted file convicted a live row this way — see
        // [`TypeInventory::adjudicable`].
        if self.adjudicable() {
            for (name, _, _) in ALLOWED_COLLISIONS {
                if !self.collisions.iter().any(|c| &c.name == name) {
                    errors.push(format!(
                        "STALE ALLOWANCE: {name} no longer collides — prune the \
                         row (an allowance for a non-existent duplication is \
                         drift)"
                    ));
                }
            }
        }

        // Stale vocabulary-split row: same anti-drift discipline as the
        // allowance table. A triage row for a split that no longer exists
        // means the resolution LANDED and nobody pruned the row — which is
        // how a resolved finding keeps reading as open debt.
        if self.adjudicable() {
            for (name, set, owner, _) in VOCABULARY_SPLITS {
                let live = self.vocabulary_splits().into_iter().any(|c| {
                    let mut keys: Vec<&str> = c.crates.iter().map(String::as_str).collect();
                    keys.sort_unstable();
                    &c.name == name && keys.join("+") == *set
                });
                if !live {
                    errors.push(format!(
                        "STALE VOCABULARY-SPLIT ROW: {name} ({set}) no longer \
                         splits — the resolution owned by {owner} has landed; \
                         prune the row (a triage row for a non-existent split \
                         reports resolved work as open debt)"
                    ));
                }
            }
        }

        // Stale named zero: a crate whose declared zero has been FILLED.
        // The allowance table has had this leg since it was written and this
        // table has not, so a row could keep asserting "owns no type yet"
        // about a crate that grew three enums — measured 2026-09-03 on
        // `finding-dispatch`, caught only because one test happened to pin
        // the exact zero list.
        if self.adjudicable() {
            for (name, _) in NAMED_ZEROS {
                let Some(c) = self.crates.iter().find(|c| c.crate_name == *name) else {
                    errors.push(format!(
                        "STALE NAMED-ZERO ROW: crate {name} is not in the \
                         workspace — prune the row (a named zero for a crate \
                         that does not exist is drift)"
                    ));
                    continue;
                };
                let filled = c.decls.iter().any(|d| !d.in_test_module);
                if filled {
                    let names: Vec<&str> = c
                        .decls
                        .iter()
                        .filter(|d| !d.in_test_module)
                        .map(|d| d.name.as_str())
                        .collect();
                    errors.push(format!(
                        "STALE NAMED-ZERO ROW: crate {name} now declares {} \
                         public type(s) ({}) — the zero was filled; prune the \
                         row (a row saying it owns no type is a false \
                         statement the gate publishes)",
                        names.len(),
                        names.join(", ")
                    ));
                }
            }
        }

        if errors.is_empty() {
            Ok(())
        } else {
            Err(errors)
        }
    }

    fn crates_scanned_is_real_workspace(&self) -> bool {
        self.generated_by == "omp-inventory-map::types_inventory"
            && self
                .crates
                .iter()
                .any(|c| c.crate_name == "omp-inventory-map")
    }

    /// May a claim ABOUT THE REPOSITORY be drawn from these records?
    ///
    /// Two conditions, and both are load-bearing. The set must be a real
    /// workspace scan (or a fixture that declares itself one), AND the tree
    /// it came from must be able to testify — [`CensusSource::Committed`] or
    /// [`CensusSource::Declared`]. The second condition is the one added on
    /// 2026-09-11, after a row was convicted as STALE by a tree that simply
    /// had an uncommitted deletion in it: `crates/contabo-reclaim/src/model.rs`
    /// is gone from this worktree and present in HEAD, so the shared checkout
    /// says `GuardDecision` does not collide and the repository says it does.
    /// Only one of those two is a commit.
    ///
    /// This SUPPRESSES nothing in CI, which reads a clean clone and so is
    /// always [`CensusSource::Committed`]; it suppresses exactly the verdicts
    /// a scratch tree was never entitled to.
    fn adjudicable(&self) -> bool {
        self.crates_scanned_is_real_workspace() && self.source.is_authoritative()
    }
}

/// What the collision ratchet has to say about one scan.
///
/// A verdict type rather than a bare `bool` so the UNKNOWN case has a name
/// and a reason to carry: the leg that used to compare a number could only
/// pass or fail, so on a tree it had no business judging it PASSED — and a
/// pass is what everybody reads as "the repository is fine".
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RatchetVerdict {
    /// Live count sits exactly inside the band. The bound held.
    Held { count: usize },
    /// A collision was added without adjudicating it.
    Rose { count: usize, ceiling: usize },
    /// A collision was resolved and the bound was not lowered with it —
    /// banked slack, which is a future rise nobody will see.
    Slack { count: usize, ceiling: usize },
    /// No verdict is available and this is NOT a pass. `reason` names the
    /// tree that could not testify.
    NotAdjudicated { reason: String },
}

/// Apply [`UNALLOWED_COLLISION_RATCHET`] to a scan, source first.
///
/// Source FIRST is the whole point: the count is read only after the tree
/// has proven it can speak for a commit. A worktree with the identical
/// number is still [`RatchetVerdict::NotAdjudicated`], because the identity
/// would be a coincidence — measured 2026-09-11, when the shared checkout
/// read exactly the ceiling (42) while the commit it came from read 43.
#[must_use]
pub fn collision_ratchet_verdict(inventory: &TypeInventory) -> RatchetVerdict {
    if let Some(reason) = inventory.source.blocked_reason() {
        return RatchetVerdict::NotAdjudicated {
            reason: reason.to_owned(),
        };
    }
    let count = inventory.disallowed().len();
    if count > UNALLOWED_COLLISION_CEILING {
        return RatchetVerdict::Rose {
            count,
            ceiling: UNALLOWED_COLLISION_CEILING,
        };
    }
    if UNALLOWED_COLLISION_CEILING > count + UNTRACKED_COLLISION_TOLERANCE {
        return RatchetVerdict::Slack {
            count,
            ceiling: UNALLOWED_COLLISION_CEILING,
        };
    }
    RatchetVerdict::Held { count }
}

/// The environment whose verdict on this leg is BINDING, when we are in one.
///
/// CI is the oracle (see [`UNTRACKED_COLLISION_TOLERANCE`]), so CI is the one
/// place where "I could not read the repository" must be a hard failure
/// rather than a named UNKNOWN — otherwise the day git is missing from the
/// runner is the day this gate silently stops existing.
#[must_use]
pub fn binding_environment() -> Option<String> {
    for key in ["GITHUB_ACTIONS", "CI"] {
        if let Ok(value) = std::env::var(key) {
            if value == "true" || value == "1" {
                return Some(format!("{key}={value}"));
            }
        }
    }
    None
}

/// The ratchet as a GATE: verdict plus the environment, in, refusal text out.
///
/// Pure, so the one branch nobody can reach from a laptop or the lane — CI
/// failing to read the repository — is still exercised by a test rather than
/// trusted. `binding` comes from [`binding_environment`] in production.
///
/// UNKNOWN is spent as UNKNOWN OUTSIDE the oracle (returned, not raised) and
/// as a REFUSAL inside it. Both halves matter: a lane red on a tree it was
/// rsynced is noise, and an oracle that cannot read the repository yet
/// reports green is the gate quietly ceasing to exist.
pub fn collision_ratchet_gate(
    inventory: &TypeInventory,
    binding: Option<&str>,
) -> Result<RatchetVerdict, String> {
    let verdict = collision_ratchet_verdict(inventory);
    match &verdict {
        RatchetVerdict::Held { .. } => Ok(verdict),
        RatchetVerdict::Rose { count, ceiling } => Err(format!(
            "unallowed collisions rose {count} > ceiling {ceiling}: adjudicate each (allow with a true reason, rename, or unify) -- raising the ceiling is amnesty: {}",
            inventory
                .disallowed()
                .iter()
                .map(|c| c.name.as_str())
                .collect::<Vec<_>>()
                .join(",")
        )),
        RatchetVerdict::Slack { count, ceiling } => Err(format!(
            "ceiling {ceiling} exceeds live {count} + tolerance {UNTRACKED_COLLISION_TOLERANCE}: lower the ceiling, do not bank slack -- a raise must follow a measured rise"
        )),
        RatchetVerdict::NotAdjudicated { reason } => match binding {
            Some(env) => Err(format!(
                "{env} is the oracle for this leg and it could not read the repository: {reason} \
                 -- fix the checkout, never the bound"
            )),
            None => Ok(verdict),
        },
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn crate_with(name: &str, decls: &[(&str, TypeKind)]) -> CrateTypes {
        CrateTypes {
            crate_name: name.to_owned(),
            decls: decls
                .iter()
                .map(|(n, k)| TypeDecl {
                    crate_name: name.to_owned(),
                    name: n.to_string(),
                    kind: *k,
                    rel_path: "src/lib.rs".to_owned(),
                    line: 1,
                    in_test_module: false,
                })
                .collect(),
            reexports: Vec::new(),
            // Fixtures model LIBRARY crates unless a test says otherwise:
            // that is the case the named-zero legs are about.
            has_lib: true,
        }
    }

    /// A DECLARED inventory carrying exactly `count` unallowed collisions.
    ///
    /// Synthetic names (`RatchetSpecimenN`) so the fixture can never pick up
    /// a real allowance row by accident — the count is ours, stated, and
    /// independent of whatever the workspace happens to hold today.
    fn inventory_with_disallowed(count: usize) -> TypeInventory {
        let names: Vec<String> = (0..count).map(|i| format!("RatchetSpecimen{i}")).collect();
        let decls: Vec<(&str, TypeKind)> = names
            .iter()
            .map(|n| (n.as_str(), TypeKind::Struct))
            .collect();
        let inventory = assemble(vec![
            crate_with("ratchet-left", &decls),
            crate_with("ratchet-right", &decls),
        ]);
        assert_eq!(
            inventory.disallowed().len(),
            count,
            "the specimen must carry the count it claims"
        );
        inventory
    }

    /// A binary-only crate: `main.rs`, no `lib.rs`, therefore no library
    /// surface that a public type could live on.
    fn binary_only_crate(name: &str) -> CrateTypes {
        CrateTypes {
            crate_name: name.to_owned(),
            decls: Vec::new(),
            reexports: Vec::new(),
            has_lib: false,
        }
    }

    #[test]
    fn every_allowed_collision_row_carries_a_nonempty_reason() {
        for (name, _, reason) in ALLOWED_COLLISIONS {
            assert!(!name.is_empty(), "allowance row with empty name");
            assert!(
                !reason.trim().is_empty(),
                "allowance row {name} has empty reason"
            );
        }
        assert!(
            !ALLOWED_COLLISIONS.is_empty(),
            "allowance table must not be silently empty"
        );
    }

    #[test]
    fn every_allowed_collision_row_carries_owner_and_dies_when() {
        for (name, pair, reason) in ALLOWED_COLLISIONS {
            assert!(
                reason.contains("owner="),
                "allowance row {name} ({pair}) missing owner=: {reason}"
            );
            assert!(
                reason.contains("dies_when="),
                "allowance row {name} ({pair}) missing dies_when=: {reason}"
            );
            let owner = reason
                .split("owner=")
                .nth(1)
                .unwrap_or("")
                .split_whitespace()
                .next()
                .unwrap_or("");
            let dies = reason.split("dies_when=").nth(1).unwrap_or("").trim();
            assert!(
                !owner.is_empty() && owner != "owner=",
                "allowance row {name} has empty owner= value"
            );
            assert!(
                !dies.is_empty(),
                "allowance row {name} has empty dies_when= value"
            );
        }
        assert!(
            !ALLOWED_COLLISIONS.is_empty(),
            "zero allowance rows is an ERROR, never a pass — anti-vacuity"
        );
    }

    #[test]
    fn every_named_zero_row_carries_a_nonempty_reason() {
        for (name, reason) in NAMED_ZEROS {
            assert!(!name.is_empty());
            assert!(
                !reason.trim().is_empty(),
                "named zero {name} has empty reason"
            );
        }
    }

    #[test]
    fn positive_control_unique_types_pass() {
        let inv = assemble(vec![
            crate_with(
                "alpha",
                &[("Alpha", TypeKind::Struct), ("AlphaKind", TypeKind::Enum)],
            ),
            crate_with("beta", &[("Beta", TypeKind::Struct)]),
        ]);
        assert!(
            inv.check().is_ok(),
            "crates with unique well-formed types must pass: {:?}",
            inv.check().unwrap_err()
        );
    }

    #[test]
    fn collision_without_allowance_fails_and_names_both_crates() {
        let inv = assemble(vec![
            crate_with("alpha", &[("Finding", TypeKind::Struct)]),
            crate_with("beta", &[("Finding", TypeKind::Struct)]),
        ]);
        let err = inv.check().expect_err("collision must fail the gate");
        assert!(
            err.iter()
                .any(|e| e.contains("alpha") && e.contains("beta")),
            "error must name BOTH crates: {err:?}"
        );
    }

    #[test]
    fn allowed_collision_passes_but_is_visible_in_output() {
        let inv = assemble(vec![
            crate_with("state-wildcard-lint", &[("Finding", TypeKind::Struct)]),
            crate_with("finding", &[("Finding", TypeKind::Struct)]),
        ]);
        inv.check().expect("allowed collision must pass");
        assert_eq!(inv.collisions.len(), 1);
        assert!(inv.collisions[0].allowance.is_some());
    }

    #[test]
    fn test_module_declarations_never_collide() {
        let mut b = crate_with(
            "beta",
            &[("Beta", TypeKind::Struct), ("Finding", TypeKind::Struct)],
        );
        // beta's Finding is inside a cfg(test) module -> not public API;
        // beta keeps a real public type so it is not a named-zero finding.
        b.decls[1].in_test_module = true;
        let inv = assemble(vec![
            crate_with("alpha", &[("Finding", TypeKind::Struct)]),
            b,
        ]);
        assert!(
            inv.check().is_ok(),
            "cfg(test) declarations must not participate in collisions: {:?}",
            inv.check().unwrap_err()
        );
    }

    #[test]
    fn anti_vacuity_zero_types_everywhere_is_an_error() {
        let inv = assemble(vec![crate_with("alpha", &[]), crate_with("beta", &[])]);
        let err = inv.check().expect_err("empty inventory must error");
        assert!(err.iter().any(|e| e.contains("anti-vacuity")), "{err:?}");
    }

    #[test]
    fn unnamed_zero_crate_requires_a_named_row() {
        let inv = assemble(vec![
            crate_with("alpha", &[("Alpha", TypeKind::Struct)]),
            crate_with("mystery", &[]),
        ]);
        let err = inv.check().expect_err("unnamed zero must error");
        assert!(err.iter().any(|e| e.contains("mystery")), "{err:?}");
    }

    #[test]
    fn reexport_only_crate_is_not_a_zero() {
        let c = CrateTypes {
            crate_name: "omp-types".to_owned(),
            decls: Vec::new(),
            reexports: vec![TypeReexport {
                crate_name: "omp-types".to_owned(),
                name: "Outcome".to_owned(),
                from: "asupersync::types".to_owned(),
            }],
            has_lib: true,
        };
        let inv = assemble(vec![crate_with("alpha", &[("Alpha", TypeKind::Struct)]), c]);
        assert!(
            inv.check().is_ok(),
            "reexport-only crate must not be a zero: {:?}",
            inv.check().unwrap_err()
        );
    }

    #[test]
    fn observation_has_a_decision_row_not_an_allowance() {
        assert!(
            !ALLOWED_COLLISIONS
                .iter()
                .any(|(n, _, _)| *n == "Observation"),
            "Observation must NOT be an allowance row"
        );
        let d = observation_seam_decision();
        assert_eq!(d.type_name, "Observation");
        assert!(d.decision.contains("CONVERGE"));
        assert!(d.shared_home.starts_with("omp-types"));
        assert_eq!(d.migration.len(), 4);
    }

    #[test]
    fn missing_vocabulary_covers_the_six_bead_rows_with_derived_statuses() {
        let want: &[(&str, MissingStatus)] = &[
            ("Grade", MissingStatus::AbsentEverywhere),
            ("DeliveryClass", MissingStatus::PresentUpstreamBlocked),
            ("AckKind", MissingStatus::PresentUpstreamBlocked),
            ("ObligationLedger", MissingStatus::PresentUpstreamUsable),
            ("Budget", MissingStatus::PresentUpstreamUsable),
            ("Outcome", MissingStatus::PresentWrongSemantics),
        ];
        let rows = missing_vocabulary();
        for (name, status) in want {
            let row = rows
                .iter()
                .find(|r| &r.name == name)
                .unwrap_or_else(|| panic!("missing row {name}"));
            assert_eq!(&row.status, status, "row {name} status drifted");
            assert!(
                row.evidence.len() > 40,
                "row {name} must carry derived evidence, not a stub"
            );
        }
        assert_eq!(rows.len(), 6, "exactly the six bead rows");
    }

    /// MUTATION (acceptance 7), on a synthetic fixture: introduce a deliberate
    /// collision, the gate goes RED naming both crates; restore
    /// byte-identically (sha-verified) and the gate goes green again.
    #[test]
    fn mutation_introduce_collision_then_restore_byte_identically() {
        let dir = std::env::temp_dir().join(format!(
            "omp-inv-mutation-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("clock")
                .as_nanos()
        ));
        let a_src = dir.join("alpha/src");
        let b_src = dir.join("beta/src");
        std::fs::create_dir_all(&a_src).expect("mkdir");
        std::fs::create_dir_all(&b_src).expect("mkdir");
        let a_file = a_src.join("lib.rs");
        let b_file = b_src.join("lib.rs");
        std::fs::write(&a_file, "pub struct Alpha;\n").expect("write a");
        let b_original = b"pub struct Beta;\n".to_vec();
        std::fs::write(&b_file, &b_original).expect("write b");

        let mut before = std::fs::read(&a_file).expect("read a");
        before.extend_from_slice(&std::fs::read(&b_file).expect("read b"));

        // MUTATE: beta now declares Alpha too -> collision
        std::fs::write(&b_file, b"pub struct Alpha;\n").expect("mutate b");

        let inv = assemble(vec![
            parse_fixture(&a_src, "alpha"),
            parse_fixture(&b_src, "beta"),
        ]);
        let err = inv.check().expect_err("deliberate collision must go RED");
        assert!(
            err.iter().any(|e| e.contains("COLLISION Alpha")
                && e.contains("alpha")
                && e.contains("beta")),
            "RED must name the type and BOTH crates: {err:?}"
        );

        // RESTORE byte-identically
        std::fs::write(&b_file, &b_original).expect("restore b");
        let mut after = std::fs::read(&a_file).expect("read a");
        after.extend_from_slice(&std::fs::read(&b_file).expect("read b"));
        assert_eq!(
            sha256_hex(&before),
            sha256_hex(&after),
            "restore must be byte-identical (sha both sides)"
        );

        let inv2 = assemble(vec![
            parse_fixture(&a_src, "alpha"),
            parse_fixture(&b_src, "beta"),
        ]);
        inv2.check().expect("restored fixture must go green");

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// Scan a fixture src dir using the same parse path as the real walker.
    fn parse_fixture(src: &Path, crate_name: &str) -> CrateTypes {
        let mut decls = Vec::new();
        let mut reexports = Vec::new();
        for f in walk(src.to_path_buf()) {
            let text = std::fs::read_to_string(&f).expect("read fixture");
            let rel = format!("src/{}", f.file_name().unwrap().to_string_lossy());
            parse_source(crate_name, &rel, &text, &mut decls, &mut reexports);
        }
        CrateTypes {
            crate_name: crate_name.to_owned(),
            decls,
            reexports,
            // Same rule as the real walker: lib.rs presence, not a guess.
            has_lib: src.join("lib.rs").is_file(),
        }
    }

    fn sha256_hex(bytes: &[u8]) -> String {
        // FNV-1a 64 is enough for byte-identity checking in a fixture test
        // without adding a crypto dependency to a scanner crate.
        let mut h: u64 = 0xcbf29ce484222325;
        for b in bytes {
            h ^= u64::from(*b);
            h = h.wrapping_mul(0x100000001b3);
        }
        format!("{h:016x}")
    }

    /// POSITIVE CONTROL on the REAL workspace. This test asserts only what
    /// (a) is true of ANY tree and (b) this crate can own.
    ///
    /// # What used to be here, and why it could never hold
    ///
    /// This test used to `assert_eq!` the collision NAME SET against a
    /// hardcoded six-name vector. It was measured wrong three ways at once
    /// on 2026-09-03, all with `omp-inventory-map types --repo <tree>`
    /// against trees extracted by `git archive`:
    ///
    /// | tree | crates | collisions |
    /// |---|---|---|
    /// | `4b398e4` — the last CI run, 2026-09-02T03:01:50Z | 51 | 8 |
    /// | `6238c0f` — HEAD, ~19h later | 69 | 29 |
    /// | the shared worktree, same minute as HEAD | 69 | 29 |
    ///
    /// The hardcoded vector said **6**. CI reported **8**. HEAD holds
    /// **29**. Eighteen crates landed in one day. So the assertion was not
    /// stale-and-fixable; it asserted a quantity that changes several times
    /// per day, that this crate does not produce, and that no lane can be
    /// held to. Worse, `scan_workspace_types` reads the WORKTREE — under a
    /// four-agent fleet this test's verdict was a function of three peers'
    /// UNCOMMITTED edits, so it could go red for a reason its own crate had
    /// no way to see, let alone fix. That is AGENTS.md rule 8 (a `cargo`
    /// figure is never evidence about a commit) expressed as a test.
    ///
    /// # What replaced it
    ///
    /// The DERIVED class, not the snapshot: a collision where one side IS
    /// [`VOCABULARY_CRATE`]. That predicate needs no maintained list, and it
    /// cut 29 collisions to the **2** that carry a real finding —
    /// `Lifecycle` and `PaneObservation`, which were exactly the two that
    /// had just appeared. The other 27 are leaf-crate coincidences
    /// (`Config`, `Row`, `Rule`, `Verdict`, `ScanError`) that the module
    /// header already NO-CLAIMs. An `assert_eq!` on the whole set could not
    /// tell those two classes apart; that is the argument, and it is why
    /// both readings of the original failure were right about different rows.
    #[test]
    fn real_workspace_today_all_collisions_accounted_and_volume_real() {
        let repo = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(|p| p.parent())
            .expect("repo root is two levels above the crate");
        let inv = scan_workspace_types(repo).expect("scan works");

        // Volume floors. Monotone by construction: the workspace only grows,
        // so a floor never re-stales upward the way an equality does.
        assert!(inv.counts.enums >= 50, "enums floor: {}", inv.counts.enums);
        assert!(
            inv.counts.structs >= 79,
            "structs floor: {}",
            inv.counts.structs
        );
        assert!(
            inv.counts.crates_with_types >= 20,
            "crates-with-types floor"
        );

        // POSITIVE CONTROL (AGENTS.md rule 2): the scanner must find the
        // crate it lives in. A census that reports nothing is
        // indistinguishable from one that works.
        assert!(
            inv.crates
                .iter()
                .any(|c| c.crate_name == "omp-inventory-map"
                    && c.decls.iter().any(|d| !d.in_test_module)),
            "scanner must see its own crate's public types"
        );
        assert!(
            !inv.collisions.is_empty(),
            "anti-vacuity on the collision leg: a real workspace with zero \
             detected collisions means the detector is broken, not that the \
             tree is clean"
        );

        // THE INVARIANT, derived: every vocabulary split against omp-types
        // is triaged with an owner and a resolution. Nothing here names a
        // count of collisions the fleet happens to have today.
        let untriaged: Vec<String> = inv
            .untriaged_vocabulary_splits()
            .iter()
            .map(|c| format!("{} ({})", c.name, c.crates.join("+")))
            .collect();
        assert!(
            untriaged.is_empty(),
            "UNTRIAGED VOCABULARY SPLIT: a leaf crate declares a public type \
             name that {VOCABULARY_CRATE} already owns. Name it in \
             VOCABULARY_SPLITS with an owner and a resolution, or delete the \
             duplicate: {untriaged:?}"
        );

        // Each triaged row must still be LIVE — a resolved split whose row
        // was never pruned reports finished work as open debt. `check` emits
        // STALE VOCABULARY-SPLIT ROW for this; assert it is silent here.
        let errs = inv
            .check()
            .expect_err("the Observation collision is REFUSED until the seam convergence lands");
        assert!(
            !errs
                .iter()
                .any(|e| e.contains("STALE VOCABULARY-SPLIT ROW")),
            "a VOCABULARY_SPLITS row no longer matches a real split: {errs:?}"
        );
        assert!(
            !errs.iter().any(|e| e.contains("STALE ALLOWANCE")),
            "an ALLOWED_COLLISIONS row no longer matches a real collision: {errs:?}"
        );

        // ACTIONABILITY: every refusal must carry the type, both crates, and
        // a site. A refusal a reader cannot act on is the unread red.
        for c in inv.disallowed() {
            assert!(
                c.crates.len() >= 2,
                "{} claims fewer than two crates",
                c.name
            );
            assert!(
                c.sites.len() >= 2,
                "{} must carry a file:line per declaring crate: {:?}",
                c.name,
                c.sites
            );
            assert!(
                errs.iter().any(|e| {
                    e.contains(&format!("COLLISION {}", c.name))
                        && c.crates.iter().all(|k| e.contains(k.as_str()))
                }),
                "refusal for {} must name the type and every crate: {errs:?}",
                c.name
            );
        }

        // Every vocabulary split must be named as one in its refusal, so the
        // sharp class is not buried in the undifferentiated wall.
        for c in inv.vocabulary_splits() {
            assert!(
                errs.iter()
                    .any(|e| e.contains(&format!("COLLISION {}", c.name))
                        && e.contains("VOCABULARY SPLIT")),
                "split {} must be labelled a VOCABULARY SPLIT: {errs:?}",
                c.name
            );
        }

        // The Observation seam keeps its DECISION and no allowance.
        let obs = inv
            .collisions
            .iter()
            .find(|c| c.name == "Observation")
            .expect("Observation collision present");
        assert!(obs.allowance.is_none(), "Observation must not be allowed");
        assert!(
            inv.seam_decisions
                .iter()
                .any(|d| d.type_name == "Observation"),
            "Observation must carry a seam decision"
        );
        assert!(
            errs.iter().any(|e| e.contains("COLLISION Observation")),
            "the gate must name the refused seam: {errs:?}"
        );

        // NAMED ZEROS, as an invariant rather than a list. The old
        // `assert_eq!(zero_names, ["finding-dispatch", "pane-dispatch-fence"])`
        // was the same drifting-snapshot defect one assertion down, and it
        // was the ONLY thing catching a filled zero because `check` had a
        // STALE ALLOWANCE leg and no STALE NAMED-ZERO leg. Measured
        // 2026-09-03: `finding-dispatch` declared zero public types at tree
        // `4b398e4` and three at HEAD, so the row asserting "owns no type
        // yet" had become false and the gate was publishing it.
        assert!(
            !inv.named_zeros.is_empty(),
            "a real workspace with no named zero at all means the zero \
             detector is broken, not that every crate owns a type"
        );
        assert!(
            !errs.iter().any(|e| e.contains("STALE NAMED-ZERO ROW")),
            "a NAMED_ZEROS row no longer describes a real zero: {errs:?}"
        );
        // Every crate reported as a named zero must actually own nothing,
        // and every actual zero must be named (the latter is `check`'s
        // NAMED-ZERO REQUIRED leg; assert it is silent).
        for reported in &inv.named_zeros {
            let name = reported.split(':').next().expect("prefix");
            let c = inv
                .crates
                .iter()
                .find(|c| c.crate_name == name)
                .unwrap_or_else(|| panic!("reported zero {name} is not a scanned crate"));
            assert!(
                !c.decls.iter().any(|d| !d.in_test_module) && c.reexports.is_empty(),
                "{name} is reported as a zero but owns output"
            );
        }
        assert!(
            !errs.iter().any(|e| e.contains("NAMED-ZERO REQUIRED")),
            "an unnamed zero crate exists — name it in NAMED_ZEROS: {errs:?}"
        );
        let omp_types = inv
            .crates
            .iter()
            .find(|c| c.crate_name == VOCABULARY_CRATE)
            .expect("omp-types present");
        assert!(
            !omp_types.reexports.is_empty(),
            "omp-types is a vocabulary crate: reexports must be non-empty"
        );
    }

    /// RATCHET (zhr29): the unallowed-collision count may fall, never rise.
    /// The ceiling equals the 2026-09-11 worktree measurement (44, including
    /// the decided Observation seam and untracked kernel-only-gate's Hit and
    /// ScanReport); a fresh clone reads fewer and passes silently, which is
    /// expected and named, not hidden. Resolving a collision (allowance row
    /// with a true reason, rename, unification) lowers the count; the ceiling
    /// follows by paired edit, never leads by raising.
    #[test]
    fn unallowed_collision_count_does_not_rise() {
        assert!(
            UNALLOWED_COLLISION_RATCHET.is_consistent(),
            "ratchet anchor drifted: ceiling and recording must move as a pair"
        );
        let repo = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(|p| p.parent())
            .expect("repo root is two levels above the crate");
        let inv = scan_workspace_types(repo).expect("scan works");
        match collision_ratchet_gate(&inv, binding_environment().as_deref()) {
            Err(refusal) => panic!("{refusal}"),
            Ok(RatchetVerdict::NotAdjudicated { reason }) => {
                // UNKNOWN, and it is spent as UNKNOWN — never as a pass on
                // the number. The leg still has to say something falsifiable
                // here, so it says what IS true: the instrument named its
                // limit, the scan it did manage is not empty, and no held
                // verdict was manufactured from a tree that cannot testify.
                assert!(
                    !reason.trim().is_empty(),
                    "a non-adjudicated verdict MUST name the tree that could not testify"
                );
                assert!(
                    !inv.crates.is_empty() && inv.counts.enums + inv.counts.structs > 0,
                    "anti-vacuity: an empty scan is an error, not an excuse to skip the ratchet"
                );
                assert!(
                    !matches!(
                        collision_ratchet_verdict(&inv),
                        RatchetVerdict::Held { .. }
                    ),
                    "a tree that cannot testify must NEVER produce a held verdict"
                );
            }
            Ok(_) => {}
        }
    }

    /// KNOWN-BAD, both directions of the band, on a DECLARED set so the
    /// numbers are ours and not the workspace's.
    ///
    /// `Rose` is the amnesty case (a collision added and not adjudicated);
    /// `Slack` is the banked-slack case (a collision resolved and the bound
    /// left high, which hides the next rise). The band is `live <= ceiling
    /// <= live + TOLERANCE`, and with TOLERANCE at 0 that is equality — so
    /// one over and one under must BOTH refuse.
    #[test]
    fn the_ratchet_refuses_a_rise_and_refuses_banked_slack() {
        let held = inventory_with_disallowed(UNALLOWED_COLLISION_CEILING);
        assert_eq!(
            collision_ratchet_verdict(&held),
            RatchetVerdict::Held {
                count: UNALLOWED_COLLISION_CEILING
            },
            "known-good: exactly the ceiling must hold"
        );

        let rose = inventory_with_disallowed(UNALLOWED_COLLISION_CEILING + 1);
        assert_eq!(
            collision_ratchet_verdict(&rose),
            RatchetVerdict::Rose {
                count: UNALLOWED_COLLISION_CEILING + 1,
                ceiling: UNALLOWED_COLLISION_CEILING
            },
            "one unadjudicated collision above the ceiling must refuse"
        );

        let slack = inventory_with_disallowed(UNALLOWED_COLLISION_CEILING - 1);
        assert_eq!(
            collision_ratchet_verdict(&slack),
            RatchetVerdict::Slack {
                count: UNALLOWED_COLLISION_CEILING - 1,
                ceiling: UNALLOWED_COLLISION_CEILING
            },
            "a resolved collision with the bound left high must refuse as slack"
        );
        // The GATE, not just the verdict: each refusal must carry its own
        // message, and the rise must NAME the specimens (a bare count tells
        // the next reader nothing about which name to adjudicate).
        let rose_message = collision_ratchet_gate(&rose, None)
            .expect_err("a rise must refuse regardless of environment");
        assert!(
            rose_message.contains("rose")
                && rose_message.contains("amnesty")
                && rose_message.contains("RatchetSpecimen0"),
            "the rise refusal must name the offenders: {rose_message}"
        );
        let slack_message = collision_ratchet_gate(&slack, None)
            .expect_err("banked slack must refuse regardless of environment");
        assert!(
            slack_message.contains("do not bank slack"),
            "the slack refusal must say what to do: {slack_message}"
        );
        collision_ratchet_gate(&held, Some("GITHUB_ACTIONS=true"))
            .expect("known-good: the ceiling holds in the oracle too");
    }

    /// UNKNOWN is spent differently in the two environments, and BOTH halves
    /// are load-bearing.
    ///
    /// Off-oracle (a laptop, the rch lane, which is rsynced WITHOUT `.git`)
    /// an unreadable repository is a named UNKNOWN, not a red: the tree was
    /// never the commit and a red there is noise nobody can act on. IN the
    /// oracle it is a hard refusal — the day CI cannot read the repository
    /// is the day this gate stops existing, and it must say so rather than
    /// report green. That branch is unreachable from every machine that runs
    /// this suite, which is exactly why it is tested here and not trusted.
    #[test]
    fn an_unreadable_repository_is_unknown_off_oracle_and_fatal_inside_it() {
        let mut scratch = inventory_with_disallowed(UNALLOWED_COLLISION_CEILING);
        scratch.source = CensusSource::Worktree {
            reason: "no .git in this tree".to_owned(),
        };

        let off_oracle = collision_ratchet_gate(&scratch, None)
            .expect("off the oracle an unreadable tree is UNKNOWN, not a refusal");
        assert!(
            matches!(off_oracle, RatchetVerdict::NotAdjudicated { .. }),
            "and UNKNOWN is what it must return — never Held: {off_oracle:?}"
        );

        let in_oracle = collision_ratchet_gate(&scratch, Some("GITHUB_ACTIONS=true"))
            .expect_err("the oracle must refuse a repository it cannot read");
        assert!(
            in_oracle.contains("GITHUB_ACTIONS=true")
                && in_oracle.contains("no .git in this tree")
                && in_oracle.contains("fix the checkout, never the bound"),
            "the oracle refusal must name the environment, the cause, and the \
             remedy that is NOT moving the bound: {in_oracle}"
        );
    }

    /// The defect this whole source-awareness exists for, as a test.
    ///
    /// A scratch tree holding EXACTLY the ceiling still yields no verdict.
    /// That identity is what happened on 2026-09-11: the shared worktree
    /// read 42 with the ceiling at 42 and reported green all day, while the
    /// commit underneath it read 43 and CI was red. A pass that agrees with
    /// the bound by coincidence is the most expensive kind.
    #[test]
    fn a_tree_that_cannot_testify_never_passes_the_ratchet() {
        let mut scratch = inventory_with_disallowed(UNALLOWED_COLLISION_CEILING);
        scratch.source = CensusSource::Worktree {
            reason: "1 census input(s) under crates/ differ from HEAD deadbeefcafe: \
                     crates/contabo-reclaim/src/model.rs"
                .to_owned(),
        };
        let verdict = collision_ratchet_verdict(&scratch);
        assert!(
            matches!(verdict, RatchetVerdict::NotAdjudicated { ref reason }
                if reason.contains("crates/contabo-reclaim/src/model.rs")),
            "the refusal must carry the tree's reason: {verdict:?}"
        );

        // MUTATION, REVERTED: make the same records authoritative and the
        // verdict appears. Without this leg the test above would also pass
        // against a function that never adjudicates anything.
        scratch.source = CensusSource::Committed {
            rev: "0".repeat(40),
        };
        assert_eq!(
            collision_ratchet_verdict(&scratch),
            RatchetVerdict::Held {
                count: UNALLOWED_COLLISION_CEILING
            },
            "the identical records, from a commit, must adjudicate"
        );
    }

    /// A scratch tree cannot convict an allowance row of being stale.
    ///
    /// BOTH controls, because suppression is exactly the kind of change that
    /// silently turns a leg off: DECLARED records convict the row (the leg
    /// still works), the same records marked as a worktree do not.
    #[test]
    fn a_scratch_tree_cannot_declare_an_allowance_row_stale() {
        // A real-looking workspace in which NO allowance row collides.
        let mut inv = assemble(vec![
            crate_with("omp-inventory-map", &[("InventoryMap", TypeKind::Struct)]),
            crate_with("omp-types", &[("Budget", TypeKind::Struct)]),
        ]);
        inv.named_zeros = Vec::new();

        let declared = inv.check().err().unwrap_or_default();
        let stale: Vec<&String> = declared
            .iter()
            .filter(|e| e.contains("STALE ALLOWANCE"))
            .collect();
        assert_eq!(
            stale.len(),
            ALLOWED_COLLISIONS.len(),
            "known-good: a declared set with no collisions must convict EVERY \
             allowance row, or this control proves nothing: {declared:?}"
        );

        inv.source = CensusSource::Worktree {
            reason: "26 census input(s) under crates/ differ from HEAD".to_owned(),
        };
        let scratch = inv.check().err().unwrap_or_default();
        assert!(
            !scratch.iter().any(|e| e.contains("STALE ALLOWANCE")),
            "a tree that is not a commit must not convict a live row: {scratch:?}"
        );
    }

    /// The instrument itself, against the tree the test is running in.
    ///
    /// Whichever branch this repo is in, the answer must be SPECIFIC: a
    /// committed scan names a 40-hex rev, a worktree scan names what differs.
    /// An empty or generic reason would make the UNKNOWN unreadable, which is
    /// the failure mode the type exists to prevent.
    #[test]
    fn the_census_names_the_tree_it_read() {
        let repo = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(|p| p.parent())
            .expect("repo root is two levels above the crate");
        match census_source(repo) {
            CensusSource::Committed { rev } => {
                assert_eq!(rev.len(), 40, "a committed source must name HEAD: {rev}");
                assert!(
                    rev.chars().all(|c| c.is_ascii_hexdigit()),
                    "a committed source must name a commit id: {rev}"
                );
            }
            CensusSource::Worktree { reason } => {
                assert!(
                    reason.contains("census input(s)") || reason.contains(GIT),
                    "a worktree source must name the divergence or the failed \
                     probe, never just decline: {reason}"
                );
            }
            CensusSource::Declared => {
                panic!("a filesystem scan can never be Declared — that is the fixture source")
            }
        }

        // The predicate that decides authority, on both sides. A census
        // input and a path that merely lives under crates/.
        assert!(is_census_input("crates/omp-inventory-map/src/types_inventory.rs"));
        assert!(is_census_input("crates/omp-inventory-map/Cargo.toml"));
        assert!(!is_census_input("crates/omp-inventory-map/tests/inventory.rs"));
        assert!(!is_census_input("crates/omp-inventory-map/artifacts/x.toml"));
        assert!(!is_census_input("docs/plan/00-brief.md"));
    }

    /// The STALE NAMED-ZERO leg, on fixtures, with BOTH controls.
    ///
    /// The leg only runs on the REAL workspace (a synthetic set has no
    /// business being told its rows are stale), so the fixture must LOOK
    /// real: `crates_scanned_is_real_workspace` keys on `generated_by` plus
    /// the presence of a crate named `omp-inventory-map`.
    #[test]
    fn stale_named_zero_row_is_refused_when_the_zero_gets_filled() {
        let declared_zero = NAMED_ZEROS[0].0;
        // Every row must be present as a real zero, or the leg reports the
        // OTHER rows as absent and the control proves nothing.
        let all_zeros = || {
            let mut set = vec![crate_with(
                "omp-inventory-map",
                &[("InventoryMap", TypeKind::Struct)],
            )];
            set.extend(NAMED_ZEROS.iter().map(|(n, _)| crate_with(n, &[])));
            set
        };

        // NEGATIVE CONTROL: every row is live (crate owns nothing) -> silent.
        let live = assemble(all_zeros());
        assert!(
            live.crates_scanned_is_real_workspace(),
            "the fixture must satisfy the real-workspace guard or this test \
             proves nothing"
        );
        let errs = live.check().err().unwrap_or_default();
        assert!(
            !errs.iter().any(|e| e.contains("STALE NAMED-ZERO ROW")),
            "a live named zero must not be reported stale: {errs:?}"
        );

        // POSITIVE CONTROL: fill one zero -> refused, naming the crate AND
        // the types that filled it.
        let mut mutated = all_zeros();
        let target = mutated
            .iter_mut()
            .find(|c| c.crate_name == declared_zero)
            .expect("declared zero is in the fixture");
        *target = crate_with(declared_zero, &[("SupervisorDecision", TypeKind::Enum)]);
        let filled = assemble(mutated);
        let errs = filled.check().expect_err("a filled named zero must go RED");
        assert!(
            errs.iter().any(|e| e.contains("STALE NAMED-ZERO ROW")
                && e.contains(declared_zero)
                && e.contains("SupervisorDecision")),
            "the refusal must name the crate and what filled it: {errs:?}"
        );

        // A row for a crate that is not in the workspace at all is also drift.
        let absent = assemble(vec![crate_with(
            "omp-inventory-map",
            &[("InventoryMap", TypeKind::Struct)],
        )]);
        let errs = absent
            .check()
            .expect_err("a row for an absent crate is drift");
        assert!(
            errs.iter()
                .any(|e| e.contains("STALE NAMED-ZERO ROW") && e.contains("not in the workspace")),
            "an absent named-zero crate must be reported: {errs:?}"
        );

        // BINARY-ONLY: no library surface, so neither a finding nor a zero
        // to name. This is the leg that replaced pane-dispatch-fence's row.
        let mut with_bin = all_zeros();
        with_bin.push(binary_only_crate("plan-assemble"));
        let inv = assemble(with_bin);
        let errs = inv.check().err().unwrap_or_default();
        assert!(
            !errs.iter().any(|e| e.contains("plan-assemble")),
            "a binary-only crate must not be asked to name its zero: {errs:?}"
        );
        assert!(
            !inv.named_zeros.iter().any(|z| z.contains("plan-assemble")),
            "a binary-only crate is not a named zero either"
        );

        // NEGATIVE CONTROL for that leg — the exemption must be about
        // has_lib and NOT about being empty: the SAME empty crate WITH a
        // library surface is still a finding. Without this control the
        // has_lib skip would be indistinguishable from silencing every
        // empty crate.
        let mut with_lib = all_zeros();
        with_lib.push(crate_with("plan-assemble", &[]));
        let errs = assemble(with_lib)
            .check()
            .expect_err("an empty LIBRARY crate is still a finding");
        assert!(
            errs.iter()
                .any(|e| e.contains("NAMED-ZERO REQUIRED") && e.contains("plan-assemble")),
            "an empty crate WITH lib.rs must still be refused: {errs:?}"
        );
    }

    /// The vocabulary-split predicate, on fixtures, with BOTH controls.
    ///
    /// A derived classifier with no fixture test is BUILT ≠ WIRED: it would
    /// be indistinguishable from one that classifies everything, or nothing.
    #[test]
    fn vocabulary_split_predicate_fires_only_against_the_vocabulary_crate() {
        // NEGATIVE CONTROL: two leaf crates colliding is NOT a split.
        let leafs = assemble(vec![
            crate_with("cargo-lane-budget", &[("Config", TypeKind::Struct)]),
            crate_with("crate-soundness-verify", &[("Config", TypeKind::Struct)]),
        ]);
        assert_eq!(
            leafs.collisions.len(),
            1,
            "the collision itself is detected"
        );
        assert!(
            leafs.vocabulary_splits().is_empty(),
            "a leaf+leaf collision must NOT be a vocabulary split"
        );

        // POSITIVE CONTROL: the same shape with omp-types on one side IS.
        let split = assemble(vec![
            crate_with(VOCABULARY_CRATE, &[("Config", TypeKind::Struct)]),
            crate_with("crate-soundness-verify", &[("Config", TypeKind::Struct)]),
        ]);
        assert_eq!(split.vocabulary_splits().len(), 1);
        assert_eq!(
            split.untriaged_vocabulary_splits().len(),
            1,
            "a split with no VOCABULARY_SPLITS row is UNTRIAGED"
        );
        let errs = split.check().expect_err("an untriaged split must go RED");
        assert!(
            errs.iter()
                .any(|e| e.contains("VOCABULARY SPLIT") && e.contains("UNTRIAGED")),
            "the refusal must say UNTRIAGED so a reader knows what to do: {errs:?}"
        );

        // The triage row must match the EXACT crate set: the same name
        // splitting from a different leaf is a new event, not a covered one.
        let (row_name, row_set, _, _) = VOCABULARY_SPLITS[0];
        let (owner, other) = row_set
            .split_once('+')
            .expect("a split row names two crates");
        let leaf = if owner == VOCABULARY_CRATE {
            other
        } else {
            owner
        };
        let covered = assemble(vec![
            crate_with(VOCABULARY_CRATE, &[(row_name, TypeKind::Enum)]),
            crate_with(leaf, &[(row_name, TypeKind::Enum)]),
        ]);
        assert!(
            covered.untriaged_vocabulary_splits().is_empty(),
            "the declared crate set must be recognised as triaged"
        );
        let elsewhere = assemble(vec![
            crate_with(VOCABULARY_CRATE, &[(row_name, TypeKind::Enum)]),
            crate_with("some-other-leaf", &[(row_name, TypeKind::Enum)]),
        ]);
        assert_eq!(
            elsewhere.untriaged_vocabulary_splits().len(),
            1,
            "{row_name} splitting against a DIFFERENT leaf is a new finding"
        );
    }

    /// [`census_source`] against a REAL git repository, because the branch
    /// that matters most cannot be reached from the machines that run this
    /// suite: the rch lane gets an rsync WITHOUT `.git`, so it only ever
    /// sees the worktree branch, and CI only ever sees the committed one.
    /// A fixture repo is the only place both are reachable at once — and a
    /// path shipped to the oracle untested is how the oracle learns to say
    /// "I cannot read the repository" and be believed.
    ///
    /// Every leg here is a control: clean commit -> Committed; a modified
    /// source -> Worktree NAMING it; an untracked `.rs` -> Worktree; and a
    /// dirty `tests/` file -> STILL Committed, which is the scoping claim
    /// `is_census_input` makes and the reason authority does not degenerate
    /// into "nobody is working".
    #[test]
    fn census_source_reads_a_real_git_repository() {
        let root = std::env::temp_dir().join(format!(
            "omp-inventory-map-census-source-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        let src = root.join("crates/specimen/src");
        std::fs::create_dir_all(&src).expect("specimen source root");
        std::fs::create_dir_all(root.join("crates/specimen/tests")).expect("specimen test root");
        std::fs::write(
            root.join("crates/specimen/Cargo.toml"),
            "[package]\nname = \"specimen\"\nversion = \"0.1.0\"\nedition = \"2021\"\n",
        )
        .expect("specimen manifest");
        std::fs::write(src.join("lib.rs"), "pub struct Specimen;\n").expect("specimen source");

        let git = |args: &[&str]| {
            let output = std::process::Command::new(GIT)
                .args(args)
                .current_dir(&root)
                .output()
                .unwrap_or_else(|e| panic!("`{GIT} {}` did not spawn: {e}", args.join(" ")));
            assert!(
                output.status.success(),
                "`{GIT} {}` failed: {}",
                args.join(" "),
                String::from_utf8_lossy(&output.stderr)
            );
        };
        git(&["init", "--quiet", "--initial-branch=main"]);
        git(&["add", "--all"]);
        git(&[
            "-c",
            "user.name=census fixture",
            "-c",
            "user.email=census@fixture.invalid",
            "commit",
            "--quiet",
            "-m",
            "specimen",
        ]);

        // KNOWN-GOOD: a clean checkout speaks for its commit.
        let committed = census_source(&root);
        let rev = match &committed {
            CensusSource::Committed { rev } => rev.clone(),
            other => panic!("a clean checkout must be Committed: {other:?}"),
        };
        assert_eq!(rev.len(), 40, "the source must carry HEAD: {rev}");
        assert!(committed.is_authoritative(), "a commit may be adjudicated");
        assert!(committed.blocked_reason().is_none());

        // SCOPING CONTROL: dirt OUTSIDE the census inputs changes nothing.
        std::fs::write(
            root.join("crates/specimen/tests/specimen.rs"),
            "// untracked test file\n",
        )
        .expect("dirty test file");
        assert_eq!(
            census_source(&root),
            CensusSource::Committed { rev: rev.clone() },
            "a file this census never reads must not cost the scan its authority"
        );

        // KNOWN-BAD 1: an untracked source under `src` is content CI cannot
        // see, so the tree stops speaking for the commit.
        std::fs::write(src.join("extra.rs"), "pub struct Extra;\n").expect("untracked source");
        let untracked = census_source(&root);
        match &untracked {
            CensusSource::Worktree { reason } => assert!(
                reason.contains("crates/specimen/src/extra.rs") && reason.contains(&rev[..12]),
                "the reason must name the path and the HEAD it diverged from: {reason}"
            ),
            other => panic!("an untracked source must refuse authority: {other:?}"),
        }
        assert!(!untracked.is_authoritative());
        std::fs::remove_file(src.join("extra.rs")).expect("revert untracked source");
        assert!(
            matches!(census_source(&root), CensusSource::Committed { .. }),
            "reverting the mutation must restore authority"
        );

        // KNOWN-BAD 2: a DELETED tracked source — the exact shape that made
        // the lane and CI disagree (`crates/contabo-reclaim/src/model.rs`).
        std::fs::remove_file(src.join("lib.rs")).expect("delete tracked source");
        match census_source(&root) {
            CensusSource::Worktree { reason } => assert!(
                reason.contains("crates/specimen/src/lib.rs"),
                "a deleted tracked source must be named: {reason}"
            ),
            other => panic!("a deleted tracked source must refuse authority: {other:?}"),
        }
        std::fs::write(src.join("lib.rs"), "pub struct Specimen;\n").expect("restore source");
        assert!(
            matches!(census_source(&root), CensusSource::Committed { .. }),
            "restoring the byte-identical source must restore authority"
        );

        // And the scan carries it end to end, not just the probe.
        let scanned = scan_workspace_types(&root).expect("fixture scan");
        assert!(
            matches!(scanned.source, CensusSource::Committed { .. }),
            "the scan must stamp what the probe measured: {:?}",
            scanned.source
        );

        // A directory with no git at all is UNKNOWN, and says why.
        let bare = std::env::temp_dir().join(format!(
            "omp-inventory-map-census-nogit-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&bare);
        std::fs::create_dir_all(&bare).expect("bare root");
        match census_source(&bare) {
            CensusSource::Worktree { reason } => assert!(
                !reason.trim().is_empty(),
                "a gitless tree must still say why it cannot testify"
            ),
            other => panic!("a tree with no git cannot be authoritative: {other:?}"),
        }
        std::fs::remove_dir_all(&bare).expect("remove bare root");
        std::fs::remove_dir_all(&root).expect("remove census fixture");
    }

    /// Every VOCABULARY_SPLITS row is well-formed: an owner that is one of
    /// the two named crates and is NOT the vocabulary crate (the leaf holding
    /// the duplicate owns the fix), and a resolution carrying real evidence
    /// rather than a stub.
    #[test]
    fn every_vocabulary_split_row_names_a_leaf_owner_and_a_resolution() {
        assert!(
            !VOCABULARY_SPLITS.is_empty(),
            "the split table must not be silently empty — an empty table and \
             a clean tree are indistinguishable without a live measurement"
        );
        for (name, set, owner, resolution) in VOCABULARY_SPLITS {
            assert!(!name.is_empty(), "split row with empty type name");
            let crates: Vec<&str> = set.split('+').collect();
            assert_eq!(crates.len(), 2, "row {name}: set must name two crates");
            let mut sorted = crates.clone();
            sorted.sort_unstable();
            assert_eq!(
                sorted, crates,
                "row {name}: crate set must be sorted, it is matched against a \
                 sorted key"
            );
            assert!(
                crates.contains(&VOCABULARY_CRATE),
                "row {name}: a vocabulary split must involve {VOCABULARY_CRATE}"
            );
            assert!(
                crates.contains(owner),
                "row {name}: owner {owner} is not one of the colliding crates"
            );
            assert_ne!(
                *owner, VOCABULARY_CRATE,
                "row {name}: the LEAF holding the duplicate owns the fix, not \
                 the vocabulary crate that legitimately declares the name"
            );
            assert!(
                resolution.len() > 120,
                "row {name}: resolution must carry derived evidence with \
                 file:line, not a stub ({} chars)",
                resolution.len()
            );
            assert!(
                resolution.contains(".rs:"),
                "row {name}: resolution must cite a file:line"
            );
        }
    }

    #[test]
    fn lifecycle_decision_is_a_decision_not_an_allowance() {
        assert!(
            !ALLOWED_COLLISIONS.iter().any(|(n, _, _)| *n == "Lifecycle"),
            "Lifecycle must NOT be an allowance row — the enums are \
             variant-identical, which is a convergence, not an accepted \
             coincidence"
        );
        let d = lifecycle_seam_decision();
        assert_eq!(d.type_name, "Lifecycle");
        assert!(d.decision.contains("CONVERGE"));
        assert!(d.shared_home.starts_with(VOCABULARY_CRATE));
        assert!(d.rationale.contains("omp-rpc-session/src/lib.rs:682"));
        assert!(d.rationale.contains("omp-types/src/lifecycle.rs:12"));
        assert_eq!(d.migration.len(), 3);

        // PaneObservation deliberately has NO decision of its own: it is
        // step 3 of the Observation migration. Two rows for one fact is the
        // defect the deleted assert_eq! carried in its own comment.
        let decided: Vec<String> = seam_decisions().into_iter().map(|d| d.type_name).collect();
        assert_eq!(decided, ["Observation", "Lifecycle"]);
        assert!(
            observation_seam_decision().migration[2].contains("PaneObservation"),
            "PaneObservation's resolution must live in the Observation \
             migration step 3"
        );
    }
}
